havior(IDType itsIdentifier = kNoIdentifier,						ResNumber itsMenuNo = kNoResource,						EventNumber itsInvalidateEvent = mInvalidateWindowMenu,						bool sortByDocument = false,						bool documentSeparators = false,						bool includeHidden = false);		// Initialize with the corresponding menu to synchronize with the behavior	virtual ~TWindowMenuBehavior();	virtual void* Clone() const; // override	virtual void DoMenuCommand(CommandNumber aCommandNumber); // override		// Selects the corresponding window	virtual void DoSetupMenus(); // override		// Updates the window menu if necessary	virtual void InvalidateWindowMenu();		// Invalidate the windows menu	virtual void BuildWindowList();		// Construct the window list that will be used to load the menu	virtual bool ShouldBeIncluded(TWindow* theWindow) const;		// Filter function returns true if a given window should be in the windows menu	virtual void UpdateWindowMenu();		// Update the windows menu (rebuilding it if necessary)	virtual bool DoToolboxEvent(TToolboxEvent* event); // override		// Filter that invalidates the windows menu when activate events are detected	virtual void DoEvent(EventNumber eventNumber,						 TEventHandler* source,						 TEvent* event); // override	virtual void GetMinMaxSize(CLongPoint_AC& minSize,							   CLongPoint_AC& maxSize,							   CSortedList_AC* windowList);		// return the smallest window max size, and the largest window min size; useful for		// doing things like tiling and stacking	bool IsWindowMenuInvalid() { return fWindowMenuInvalid; }		// true if window menu needs updating	void ValidateWindowMenu() { fWindowMenuInvalid = false; }		// Validate the windows menu (But don't update the menu)	CSortedList_AC* GetWindowList() { return &fWindowList; }		// Return the list that holds the windows to be in the windows menuprotected:	TWindowSortedList	fWindowList;			// list of windows in the menu	ResNumber			fMenuNo;				// the ID of the windows menu	EventNumber			fInvalidateEvent;		// event number that causes window menu to invalidate	short				fReserveMenuItems;		// number of items in the windows menu to leave alone	bool				fIncludeHidden;			// true to include hidden windows in the menu	bool				fDocumentSeparators;	// true to place separators between documents in the menu	bool				fWindowMenuInvalid;		// true if the windows menu is invalid and needs rebuilding};#endif // __UWINDOWMENUBEHAVIOR__